Lemma pchar_load : forall c, 0 <= c < 256 ->
  zxb (Z_to_bv 8 (nth (Z.to_nat c) TAB_IS_PATHCHAR 0)) = wz (if is_pathchar c then 1 else 0).
Proof.
  intros c Hc. unfold is_pathchar.
  assert (L : (Z.to_nat c < length TAB_IS_PATHCHAR)%nat) by (rewrite len_PCHAR; lia).
  pose proof (proj1 (forallb_forall _ _) PCHAR_01 _ (nth_In _ 0 L)) as H.
  remember (nth (Z.to_nat c) TAB_IS_PATHCHAR 0) as v eqn:EV. clear EV. cbn beta in H.
  destruct (Z.eqb_spec v 0) as [E|NE].
  - rewrite E. reflexivity.
  - cbn in H. apply Z.eqb_eq in H. rewrite H. reflexivity.
Qed.

